DROP TABLE IF EXISTS `bom`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `bom` (
  `bom_id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT 'BOM ID',
  `parent_material_id` bigint unsigned NOT NULL COMMENT '父项物料/成品ID',
  `child_material_id` bigint unsigned NOT NULL COMMENT '子项物料ID',
  `quantity` decimal(18,4) NOT NULL COMMENT '单位用量',
  `loss_rate` decimal(8,4) NOT NULL DEFAULT '0.0000' COMMENT '损耗率',
  `version_no` varchar(30) NOT NULL DEFAULT 'V1.0' COMMENT '版本号',
  `effective_date` date NOT NULL COMMENT '生效日期',
  `expire_date` date DEFAULT NULL COMMENT '失效日期',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态：1启用，0停用',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`bom_id`),
  UNIQUE KEY `uk_bom_parent_child_version` (`parent_material_id`,`child_material_id`,`version_no`),
  KEY `idx_bom_child_material_id` (`child_material_id`),
  CONSTRAINT `fk_bom_child_material` FOREIGN KEY (`child_material_id`) REFERENCES `material` (`material_id`),
  CONSTRAINT `fk_bom_parent_material` FOREIGN KEY (`parent_material_id`) REFERENCES `material` (`material_id`),
  CONSTRAINT `chk_bom_loss_rate` CHECK (((`loss_rate` >= 0) and (`loss_rate` < 1))),
  CONSTRAINT `chk_bom_not_self` CHECK ((`parent_material_id` <> `child_material_id`)),
  CONSTRAINT `chk_bom_quantity` CHECK ((`quantity` > 0)),
  CONSTRAINT `chk_bom_status` CHECK ((`status` in (0,1)))
) ENGINE=InnoDB AUTO_INCREMENT=19 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='物料清单表';
/*!40101 SET character_set_client = @saved_cs_client */;

