DROP TABLE IF EXISTS `cost_settlement`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `cost_settlement` (
  `settlement_id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '成本结算ID',
  `settlement_no` varchar(50) NOT NULL COMMENT '结算单号',
  `work_order_id` bigint unsigned NOT NULL COMMENT '工单ID',
  `order_id` bigint unsigned DEFAULT NULL COMMENT '客户订单ID',
  `material_cost` decimal(18,2) NOT NULL DEFAULT '0.00' COMMENT '材料成本',
  `labor_cost` decimal(18,2) NOT NULL DEFAULT '0.00' COMMENT '人工成本',
  `equipment_cost` decimal(18,2) NOT NULL DEFAULT '0.00' COMMENT '设备成本',
  `quality_cost` decimal(18,2) NOT NULL DEFAULT '0.00' COMMENT '质量成本',
  `other_cost` decimal(18,2) NOT NULL DEFAULT '0.00' COMMENT '其他成本',
  `total_cost` decimal(18,2) NOT NULL DEFAULT '0.00' COMMENT '总成本',
  `settlement_period` varchar(20) NOT NULL COMMENT '结算期间，如2026-07',
  `settlement_status` varchar(20) NOT NULL DEFAULT 'DRAFT' COMMENT '状态',
  `confirmed_by` bigint unsigned DEFAULT NULL COMMENT '确认人ID',
  `confirmed_at` datetime DEFAULT NULL COMMENT '确认时间',
  `exported_at` datetime DEFAULT NULL COMMENT '导出到财务系统时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`settlement_id`),
  UNIQUE KEY `uk_cost_settlement_no` (`settlement_no`),
  UNIQUE KEY `uk_cost_settlement_work_order` (`work_order_id`),
  KEY `idx_cost_settlement_order_id` (`order_id`),
  KEY `idx_cost_settlement_period` (`settlement_period`),
  KEY `idx_cost_settlement_status` (`settlement_status`),
  KEY `fk_cost_settlement_confirmed_by` (`confirmed_by`),
  CONSTRAINT `fk_cost_settlement_confirmed_by` FOREIGN KEY (`confirmed_by`) REFERENCES `user` (`user_id`),
  CONSTRAINT `fk_cost_settlement_order` FOREIGN KEY (`order_id`) REFERENCES `customer_order` (`order_id`),
  CONSTRAINT `fk_cost_settlement_work_order` FOREIGN KEY (`work_order_id`) REFERENCES `work_order` (`work_order_id`),
  CONSTRAINT `chk_cost_settlement_amount` CHECK (((`material_cost` >= 0) and (`labor_cost` >= 0) and (`equipment_cost` >= 0) and (`quality_cost` >= 0) and (`other_cost` >= 0) and (`total_cost` >= 0))),
  CONSTRAINT `chk_cost_settlement_status` CHECK ((`settlement_status` in (_utf8mb4'DRAFT',_utf8mb4'CONFIRMED',_utf8mb4'EXPORTED',_utf8mb4'CANCELLED')))
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='成本结算表';
/*!40101 SET character_set_client = @saved_cs_client */;

