  CONSTRAINT `fk_inventory_material` FOREIGN KEY (`material_id`) REFERENCES `material` (`material_id`),
  CONSTRAINT `chk_inventory_quantity` CHECK (((`quantity_on_hand` >= 0) and (`quantity_reserved` >= 0) and (`quantity_available` >= 0))),
  CONSTRAINT `chk_inventory_status` CHECK ((`inventory_status` in (_utf8mb4'NORMAL',_utf8mb4'FROZEN',_utf8mb4'INSPECTING',_utf8mb4'ISOLATED')))
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='库存表';
