  `location_code` varchar(50) DEFAULT NULL COMMENT '库位编码',
  `batch_no` varchar(80) DEFAULT NULL COMMENT '批次号',
  `related_purchase_order_id` bigint unsigned DEFAULT NULL COMMENT '关联采购订单ID',
  `related_work_order_id` bigint unsigned DEFAULT NULL COMMENT '关联工单ID',
  `handled_by` bigint unsigned DEFAULT NULL COMMENT '经办人ID',
  `handled_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '经办时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`transaction_id`),
  UNIQUE KEY `uk_inventory_transaction_no` (`transaction_no`),
  KEY `idx_inventory_transaction_inventory_id` (`inventory_id`),
  KEY `idx_inventory_transaction_material_id` (`material_id`),
  KEY `idx_inventory_transaction_type` (`transaction_type`),
  KEY `idx_inventory_transaction_handled_at` (`handled_at`),
  KEY `fk_inventory_transaction_purchase_order` (`related_purchase_order_id`),
  KEY `fk_inventory_transaction_work_order` (`related_work_order_id`),
  KEY `fk_inventory_transaction_handled_by` (`handled_by`),
  CONSTRAINT `fk_inventory_transaction_handled_by` FOREIGN KEY (`handled_by`) REFERENCES `user` (`user_id`),
  CONSTRAINT `fk_inventory_transaction_inventory` FOREIGN KEY (`inventory_id`) REFERENCES `inventory` (`inventory_id`),
  CONSTRAINT `fk_inventory_transaction_material` FOREIGN KEY (`material_id`) REFERENCES `material` (`material_id`),
  CONSTRAINT `fk_inventory_transaction_purchase_order` FOREIGN KEY (`related_purchase_order_id`) REFERENCES `purchase_order` (`purchase_order_id`),
  CONSTRAINT `fk_inventory_transaction_work_order` FOREIGN KEY (`related_work_order_id`) REFERENCES `work_order` (`work_order_id`),
  CONSTRAINT `chk_inventory_transaction_quantity` CHECK ((`quantity` > 0)),
  CONSTRAINT `chk_inventory_transaction_type` CHECK ((`transaction_type` in (_utf8mb4'PURCHASE_IN',_utf8mb4'MATERIAL_OUT',_utf8mb4'PRODUCT_IN',_utf8mb4'SALE_OUT',_utf8mb4'ADJUST_IN',_utf8mb4'ADJUST_OUT',_utf8mb4'ISOLATE_IN',_utf8mb4'ISOLATE_OUT')))
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='库存出入库流水表';
