  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`inspection_id`),
  UNIQUE KEY `uk_quality_inspection_no` (`inspection_no`),
  KEY `idx_quality_inspection_work_order_id` (`work_order_id`),
  KEY `idx_quality_inspection_work_report_id` (`work_report_id`),
  KEY `idx_quality_inspection_material_id` (`material_id`),
  KEY `idx_quality_inspection_result` (`inspection_result`),
  KEY `fk_quality_inspection_inspector` (`inspector_id`),
  CONSTRAINT `fk_quality_inspection_inspector` FOREIGN KEY (`inspector_id`) REFERENCES `user` (`user_id`),
  CONSTRAINT `fk_quality_inspection_material` FOREIGN KEY (`material_id`) REFERENCES `material` (`material_id`),
  CONSTRAINT `fk_quality_inspection_work_order` FOREIGN KEY (`work_order_id`) REFERENCES `work_order` (`work_order_id`),
  CONSTRAINT `fk_quality_inspection_work_report` FOREIGN KEY (`work_report_id`) REFERENCES `work_report` (`report_id`),
  CONSTRAINT `chk_quality_inspection_quantity` CHECK (((`sample_quantity` >= 0) and (`qualified_quantity` >= 0) and (`unqualified_quantity` >= 0))),
  CONSTRAINT `chk_quality_inspection_result` CHECK ((`inspection_result` in (_utf8mb4'PENDING',_utf8mb4'QUALIFIED',_utf8mb4'UNQUALIFIED',_utf8mb4'CONCESSION'))),
  CONSTRAINT `chk_quality_inspection_type` CHECK ((`inspection_type` in (_utf8mb4'INCOMING',_utf8mb4'PROCESS',_utf8mb4'FINAL',_utf8mb4'RECHECK')))
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='质量检验表';
