--
-- Table structure for table `work_order`
--

DROP TABLE IF EXISTS `work_order`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `work_order` (
  `work_order_id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '工单ID',
  `work_order_no` varchar(50) NOT NULL COMMENT '工单号',
  `plan_id` bigint unsigned DEFAULT NULL COMMENT '生产计划ID',
  `plan_item_id` bigint unsigned DEFAULT NULL COMMENT '生产计划明细ID',
  `material_id` bigint unsigned NOT NULL COMMENT '生产产品ID',
  `route_id` bigint unsigned DEFAULT NULL COMMENT '工艺路线ID',
  `planned_quantity` decimal(18,4) NOT NULL COMMENT '计划生产数量',
  `completed_quantity` decimal(18,4) NOT NULL DEFAULT '0.0000' COMMENT '已完成数量',
  `qualified_quantity` decimal(18,4) NOT NULL DEFAULT '0.0000' COMMENT '合格数量',
  `unqualified_quantity` decimal(18,4) NOT NULL DEFAULT '0.0000' COMMENT '不合格数量',
  `planned_start_time` datetime DEFAULT NULL COMMENT '计划开始时间',
  `planned_end_time` datetime DEFAULT NULL COMMENT '计划结束时间',
  `actual_start_time` datetime DEFAULT NULL COMMENT '实际开始时间',
  `actual_end_time` datetime DEFAULT NULL COMMENT '实际结束时间',
  `status` varchar(20) NOT NULL DEFAULT 'DRAFT' COMMENT '状态',
  `created_by` bigint unsigned DEFAULT NULL COMMENT '创建人ID',
  `released_by` bigint unsigned DEFAULT NULL COMMENT '下达人ID',
  `released_at` datetime DEFAULT NULL COMMENT '下达时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`work_order_id`),
  UNIQUE KEY `uk_work_order_no` (`work_order_no`),
  KEY `idx_work_order_plan_id` (`plan_id`),
  KEY `idx_work_order_plan_item_id` (`plan_item_id`),
  KEY `idx_work_order_material_id` (`material_id`),
  KEY `idx_work_order_status` (`status`),
  KEY `fk_work_order_route` (`route_id`),
